L119: /* The function to look up STR in the abbr table above.
L120:    This is called only on a user-specified format string.
L121:    Return `kpse_last_format' if no match.  */
L122: 
L123: static kpse_file_format_type
L124: format_abbr (const_string str)
L125: {
L126:   kpse_file_format_type ret = kpse_last_format;
L127:   unsigned a = 0;
L128: 
L129:   while (format_abbrs[a].abbr != NULL) {
L130:     if (STREQ (str, format_abbrs[a].abbr)) {
L131:       ret = format_abbrs[a].format;
L132:       break;
L133:     }
L134:     a++;
L135:   }
L136: 
L137:   return ret;
L138: }
