L276: /* Return newly-allocated NULL-terminated list of strings from MATCHES
L277:    that are prefixed with any of the subdirectories in SUBDIRS.  That
L278:    is, for a string S in MATCHES, its dirname must end with one of the
L279:    elements in SUBDIRS.  For instance, if subdir=foo/bar, that will
L280:    match a string foo/bar/baz or /some/texmf/foo/bar/baz.
L281:    We don't reallocate the actual strings, just the list elements.
L282:    Perhaps later we will implement wildcards or // or something.  */
L283: #if defined(WIN32)
L284: static string *
L285: kpathsea_subdir_match (kpathsea kpse, str_list_type subdirs,  string *matches)
L286: {
L287:   string *ret = XTALLOC1 (string);
L288:   unsigned len = 1;
L289:   unsigned e;
L290:   unsigned m;
L291:   string p;
L292: 
L293:   for (e = 0; e < STR_LIST_LENGTH (subdirs); e++) {
L294:     for (p = STR_LIST_ELT (subdirs, e); *p; p++) {
L295:       if (*p == '\\')
L296:         *p = '/';
L297:       else if (kpathsea_IS_KANJI(kpse, p))
L298:         p++;
L299:     }
L300:   }
L301:   for (m = 0; matches[m]; m++) {
L302:     unsigned loc;
L303:     string s = xstrdup (matches[m]);
L304:     for (loc = strlen (s); loc > 0 && !IS_DIR_SEP_CH (s[loc-1]); loc--)
L305:       ;
L306:     while (loc > 0 && IS_DIR_SEP_CH (s[loc-1])) {
L307:       loc--;
L308:     }
L309:     s[loc] = 0;  /* wipe out basename */
L310:     for (e = 0; e < STR_LIST_LENGTH (subdirs); e++) {
L311:       string subdir = STR_LIST_ELT (subdirs, e);
L312:       unsigned subdir_len = strlen (subdir);
L313:       while (subdir_len > 0 && IS_DIR_SEP_CH (subdir[subdir_len-1])) {
L314:         subdir_len--;
L315:         subdir[subdir_len] = 0; /* remove trailing slashes from subdir spec */
L316:       }
L317:       if (FILESTRCASEEQ (subdir, s + loc - subdir_len)) {
L318:         /* matched, save this one.  */
L319:         XRETALLOC (ret, len + 1, string);
L320:         ret[len-1] = matches[m];
L321:         len++;
L322:       }
L323:     }
L324:     free (s);
L325:   }
L326:   ret[len-1] = NULL;
L327:   return ret;
L328: }
L329: #else /* WIN32 */
L330: static string *
L331: subdir_match (str_list_type subdirs,  string *matches)
L332: {
L333:   string *ret = XTALLOC1 (string);
L334:   unsigned len = 1;
L335:   unsigned e;
L336:   unsigned m;
L337: 
L338:   for (m = 0; matches[m]; m++) {
L339:     unsigned loc;
L340:     string s = xstrdup (matches[m]);
L341:     for (loc = strlen (s); loc > 0 && !IS_DIR_SEP_CH (s[loc-1]); loc--)
L342:       ;
L343:     while (loc > 0 && IS_DIR_SEP_CH (s[loc-1])) {
L344:       loc--;
L345:     }
L346:     s[loc] = 0;  /* wipe out basename */
L347:     for (e = 0; e < STR_LIST_LENGTH (subdirs); e++) {
L348:       string subdir = STR_LIST_ELT (subdirs, e);
L349:       unsigned subdir_len = strlen (subdir);
L350:       while (subdir_len > 0 && IS_DIR_SEP_CH (subdir[subdir_len-1])) {
L351:         subdir_len--;
L352:         subdir[subdir_len] = 0; /* remove trailing slashes from subdir spec */
L353:       }
L354:       if (FILESTRCASEEQ (subdir, s + loc - subdir_len)) {
L355:         /* matched, save this one.  */
L356:         XRETALLOC (ret, len + 1, string);
L357:         ret[len-1] = matches[m];
L358:         len++;
L359:       }
L360:     }
L361:     free (s);
L362:   }
L363:   ret[len-1] = NULL;
L364:   return ret;
L365: }
L366: #endif /* WIN32 */
