L368: 
L369: /* Look up a single filename NAME, filtering by given subdirectories if
L370:    -subdir was specified.  Print all matches if global `show_all' is
L371:    true, else just the first match.  Return 0 if success, 1 if failure.  */
L372: 
L373: static unsigned
L374: lookup (kpathsea kpse, string name)
L375: {
L376:   int i;
L377:   string ret = NULL;
L378:   string *ret_list = NULL;
L379:   if (user_path) {
L380:     /* Translate ; to : if that's our ENV_SEP.  See cnf.c.  */
L381:     if (IS_ENV_SEP (':')) {
L382:       string loc;
L383:       for (loc = user_path; *loc; loc++) {
L384:         if (*loc == ';')
L385:           *loc = ':';
L386:       }
L387:     }
L388:     user_path = kpathsea_path_expand (kpse, user_path);
L389:     if (show_all) {
L390:       ret_list = kpathsea_all_path_search (kpse, user_path, name);
L391:     } else {
L392:       ret = kpathsea_path_search (kpse, user_path, name, must_exist);
L393:     }
L394:   } else {
L395:     /* No user-specified search path, check user format or guess from NAME.  */
L396:     kpse_file_format_type fmt = find_format (kpse, name, true);
L397:     switch (fmt) {
L398:       case kpse_pk_format:
L399:       case kpse_gf_format:
L400:       case kpse_any_glyph_format:
L401:         {
L402:           kpse_glyph_file_type glyph_ret;
L403:           string temp = remove_suffix (name);
L404:           /* Try to extract the resolution from the name.  */
L405:           unsigned local_dpi = find_dpi (name);
L406:           if (!local_dpi)
L407:             local_dpi = dpi;
L408:           if (show_all) {
L409:             /* Because the whole glyph lookup thing is too complicated
L410:                to try all the alternatives (cmr10.600pk vs.
L411:                dpi600/cmr10.pk, just for starters).  Patches welcome :).  */
L412:             WARNING1 ("kpsewhich: Ignoring --all for bitmap font, sorry: %s",
L413:                       name);
L414:           }
L415:           ret = kpathsea_find_glyph (kpse, temp,
L416:                                      local_dpi, fmt, &glyph_ret);
L417:           if (temp != name)
L418:             free (temp);
L419:         }
L420:         break;
L421:       case kpse_last_format:
L422:         /* If the suffix isn't recognized, assume it's a tex file. */
L423:         fmt = kpse_tex_format;
L424:         /* fall through */
L425: 
L426:       default:
L427:         if (show_all) {
L428:           ret_list = kpathsea_find_file_generic (kpse, name, fmt,
L429:                                                  must_exist, true);
L430:         } else {
L431:           ret = kpathsea_find_file (kpse, name, fmt, must_exist);
L432:         }
L433:     }
L434:   }
L435:   /* Turn single return into a null-terminated list for uniform treatment.  */
L436:   if (ret) {
L437:     ret_list = XTALLOC (2, string);
L438:     ret_list[0] = ret;
L439:     ret_list[1] = NULL;
L440:   }
L441: 
L442:   /* Filter by subdirectories, if specified.  */
L443:   if (!STR_LIST_EMPTY (subdir_paths)) {
L444: #if defined(WIN32)
L445:     string *new_list = kpathsea_subdir_match (kpse, subdir_paths, ret_list);
L446: #else
L447:     string *new_list = subdir_match (subdir_paths, ret_list);
L448: #endif /* WIN32 */
L449:     free (ret_list);
L450:     ret_list = new_list;
L451:   }
L452:   /* Print output.  */
L453:   if (ret_list) {
L454:     for (i = 0; ret_list[i]; i++)
L455: #ifdef WIN32
L456:       kpathsea_win32_puts (kpse, ret_list[i]);
L457: #else
L458:       puts (ret_list[i]);
L459: #endif
L460:     /* Save whether we found anything */
L461:     ret = ret_list[0];
L462:     free (ret_list);
L463:   }
L464: 
L465:   return ret == NULL;
L466: }
