L469: /* Help message.  */
L470: #define USAGE "\n\
L471: Standalone path lookup and expansion for the Kpathsea library.\n\
L472: The default is to look up each FILENAME in turn and report its\n\
L473: first match (if any) to standard output.\n\
L474: \n\
L475: If multiple FILENAMEs are given and a given file is not found, a blank\n\
L476: line is written to standard output.\n\
L477: \n\
L478: When looking up format (.fmt/.base/.mem) files, it is usually necessary\n\
L479: to also use -engine, or nothing will be returned; in particular,\n\
L480: -engine=/ will return matching format files for any engine.\n\
L481: \n\
L482: The exit status is 0 if all files are found, nonzero otherwise.\n\
L483: \n\
L484: -all                   output all matches, one per line (no effect with pk/gf).\n\
L485: [-no]-casefold-search  fall back to case-insensitive search if no exact match.\n\
L486: -cnf-line=STRING       handle STRING as a configuration file line.\n\
L487: -debug=NUM             set debugging flags.\n\
L488: -D, -dpi=NUM           use a base resolution of NUM; default 600.\n\
L489: -engine=STRING         set engine name to STRING.\n\
L490: -expand-braces=STRING  output variable and brace expansion of STRING.\n\
L491: -expand-path=STRING    output complete path expansion of STRING.\n\
L492: -expand-var=STRING     output variable expansion of STRING.\n\
L493: -format=NAME           use file type NAME (list shown by -help-formats).\n\
L494: -help                  display this message and exit.\n\
L495: -help-formats          display information about all supported file formats.\n\
L496: -interactive           ask for additional filenames to look up.\n\
L497: [-no]-mktex=FMT        disable/enable mktexFMT generation (FMT=pk/mf/tex/tfm).\n\
L498: -mode=STRING           set device name for $MAKETEX_MODE to STRING; no default.\n\
L499: -must-exist            search the disk as well as ls-R if necessary.\n\
L500: -path=STRING           search in the path STRING.\n\
L501: -progname=STRING       set program name to STRING.\n\
L502: -safe-in-name=STRING   check if STRING is ok to open for input.\n\
L503: -safe-out-name=STRING  check if STRING is ok to open for output.\n\
L504: -safe-extended-in-name=STRING   also check TEXMF[SYS]VAR.\n\
L505: -safe-extended-out-name=STRING  also check TEXMF[SYS]VAR.\n\
L506: -show-path=TYPE        output search path for file type TYPE\n\
L507:                          (list shown by -help-formats).\n\
L508: -subdir=STRING         only output matches whose directory ends with STRING.\n\
L509: -var-brace-value=STRING output brace-expanded value of variable STRING.\n\
L510: -var-value=STRING       output variable-expanded value of variable STRING.\n\
L511: -version               display version information number and exit.\n \
L512: "
L513: static void
L514: help_message (kpathsea kpse, string *argv)
L515: {
L516:   printf ("Usage: %s [OPTION]... [FILENAME]...\n", argv[0]);
